#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size;

    DSU(int n) : parent(n), size(n, 1) {
        iota(parent.begin(), parent.end(), 0);
    }

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (size[a] < size[b]) swap(a, b);
        parent[b] = a;
        size[a] += size[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;
    int V = N * M;

    vector<long long> power(V);
    for (auto &x : power) cin >> x;

    vector<int> order(V);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        return power[a] < power[b];
    });

    vector<long long> level(2 * V), mass(2 * V);
    vector<int> par(2 * V, -1);
    for (int i = 0; i < V; ++i) {
        level[i] = mass[i] = power[i];
    }

    DSU dsu(V);
    vector<char> active(V, false);
    vector<int> treeRoot(V);
    iota(treeRoot.begin(), treeRoot.end(), 0);

    auto neighbors = [&](int v, auto &&fn) {
        int r = v / M, c = v % M;
        if (r > 0) fn(v - M);
        if (r + 1 < N) fn(v + M);
        if (c > 0) fn(v - 1);
        if (c + 1 < M) fn(v + 1);
    };

    int nodeCount = V;

    for (int i = 0; i < V;) {
        int j = i;
        long long t = power[order[i]];
        while (j < V && power[order[j]] == t) ++j;

        for (int k = i; k < j; ++k) {
            int v = order[k];
            active[v] = true;
        }

        vector<pair<int, int>> oldLinks;
        for (int k = i; k < j; ++k) {
            int v = order[k];
            neighbors(v, [&](int u) {
                if (active[u] && power[u] < t) {
                    int root = dsu.find(u);
                    oldLinks.emplace_back(v, treeRoot[root]);
                }
            });
        }

        for (int k = i; k < j; ++k) {
            int v = order[k];
            neighbors(v, [&](int u) {
                if (active[u]) dsu.unite(v, u);
            });
        }

        vector<pair<int, int>> records;
        records.reserve((j - i) + oldLinks.size());

        for (int k = i; k < j; ++k) {
            int v = order[k];
            records.emplace_back(dsu.find(v), v);
        }
        for (auto [v, oldNode] : oldLinks) {
            records.emplace_back(dsu.find(v), oldNode);
        }

        sort(records.begin(), records.end());
        records.erase(unique(records.begin(), records.end()), records.end());

        for (size_t a = 0; a < records.size();) {
            size_t b = a;
            int root = records[a].first;
            long long total = 0;
            int newNode = nodeCount++;

            level[newNode] = t;
            while (b < records.size() && records[b].first == root) {
                int child = records[b].second;
                par[child] = newNode;
                total += mass[child];
                ++b;
            }
            mass[newNode] = total;
            treeRoot[root] = newNode;
            a = b;
        }

        i = j;
    }

    int LOG = 1;
    while ((1 << LOG) <= nodeCount) ++LOG;

    vector<vector<int>> up(LOG, vector<int>(nodeCount, -1));
    for (int v = 0; v < nodeCount; ++v) up[0][v] = par[v];
    for (int k = 1; k < LOG; ++k) {
        for (int v = 0; v < nodeCount; ++v) {
            int mid = up[k - 1][v];
            if (mid != -1) up[k][v] = up[k - 1][mid];
        }
    }

    vector<int> finalNode(nodeCount);
    for (int v = nodeCount - 1; v >= 0; --v) {
        int x = v;
        for (int k = LOG - 1; k >= 0; --k) {
            int ancestor = up[k][x];
            if (ancestor != -1 && level[ancestor] <= mass[v]) x = ancestor;
        }
        finalNode[v] = (x == v ? v : finalNode[x]);
    }

    for (int r = 0; r < N; ++r) {
        for (int c = 0; c < M; ++c) {
            int v = r * M + c;
            int x = v;
            for (int k = LOG - 1; k >= 0; --k) {
                int ancestor = up[k][x];
                if (ancestor != -1 && level[ancestor] <= power[v]) x = ancestor;
            }
            cout << mass[finalNode[x]] << (c + 1 == M ? '\n' : ' ');
        }
    }

    return 0;
}
